package pe.greenminds.ecomind.community.infrastructure.persistence.jpa.adapters;
import java.util.List;import org.springframework.stereotype.Repository;import pe.greenminds.ecomind.community.domain.model.aggregates.CommunityAchievement;import pe.greenminds.ecomind.community.domain.repositories.CommunityAchievementRepository;import pe.greenminds.ecomind.community.infrastructure.persistence.jpa.assemblers.CommunityAchievementPersistenceAssembler;import pe.greenminds.ecomind.community.infrastructure.persistence.jpa.repositories.CommunityAchievementPersistenceRepository;
@Repository public class CommunityAchievementRepositoryImpl implements CommunityAchievementRepository{private final CommunityAchievementPersistenceRepository repository;public CommunityAchievementRepositoryImpl(CommunityAchievementPersistenceRepository r){repository=r;}public CommunityAchievement save(CommunityAchievement a){return CommunityAchievementPersistenceAssembler.toDomain(repository.save(CommunityAchievementPersistenceAssembler.toEntity(a)));}public List<CommunityAchievement> findAll(Long c){return (c==null?repository.findAll():repository.findByCommunityId(c)).stream().map(CommunityAchievementPersistenceAssembler::toDomain).toList();}}
